WITH profit_by_cc AS (SELECT cc.cc_call_center_sk, cc.cc_name, SUM(cs.cs_net_profit) AS total_net_profit, CASE WHEN SUM(cs.cs_net_profit) >= 1000000 THEN 'High' WHEN SUM(cs.cs_net_profit) >= 500000 THEN 'Medium' ELSE 'Low' END AS profit_category FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN time_dim td ON cs.cs_sold_time_sk = td.t_time_sk WHERE td.t_hour BETWEEN 9 AND 17 GROUP BY cc.cc_call_center_sk, cc.cc_name) SELECT cc_sk, cc_name, total_net_profit, profit_category, profit_rank FROM (SELECT cc_call_center_sk AS cc_sk, cc_name, total_net_profit, profit_category, RANK() OVER (ORDER BY total_net_profit DESC) AS profit_rank FROM profit_by_cc) t WHERE profit_rank <= 5 ORDER BY profit_rank
